{"script":"cd log_folder || { echo "0"; exit 0; }
shopt -s nullglob
count=0
threshold=$(date -d "30 days ago" +%s)
for f in log_*.txt; do
  [ -f "$f" ] || continue
  d=${f#log_}
  d=${d%.txt}
  if ! date -d "$d" >/dev/null 2>&1; then continue; fi
  if [ "$(date -d "$d" +%s)" -le "$threshold" ]; then count=$((count+1)); fi
done
echo "$count""}

{"script":"cd log_folder || { echo "NO_DIR"; exit 0; }
python3 - <<'PY'
import os, datetime
now=datetime.date.today()
th=now - datetime.timedelta(days=30)
count=0
for fn in os.listdir('.'):
    if not fn.startswith('log_') or not fn.endswith('.txt'):
        continue
    d=fn[4:-4]
    try:
        y,m,day=map(int,d.split('-'))
        dt=datetime.date(y,m,day)
    except:
        continue
    if dt<=th:
        count+=1
print(count)
PY"}
